mapper.select:
SELECT b.id, b.device_id, d.name AS device_name, b.start_at AS `start`, b.end_at AS `end`, b.status
FROM booking b JOIN device d ON d.id = b.device_id
WHERE b.user_id = #{userId}

    AND b.start_at < #{end} AND b.end_at > #{start}

ORDER BY b.start_at DESC, b.id DESC LIMIT 101

SELECT COUNT(*) FROM booking
WHERE device_id = #{deviceId} AND status = 'CONFIRMED'
  AND start_at < #{end} AND end_at > #{start}
